{
  "findings": [
    {
      "check_id": "CKV_GCP_32",
      "title": "Unrestricted ingress access to TCP ports 80, 443, and 8080",
      "resource": "google_compute_firewall.allow_http_https",
      "severity": "CRITICAL",
      "explanation": "The firewall rule allows traffic from 0.0.0.0/0, exposing ports 80, 443, and 8080 to the entire internet."
    }
  ],
  "patched_code": "resource \"google_compute_firewall\" \"allow_http_https\" {\n  name    = \"digital-asset-trading-platform-firewall-web\"\n  network = google_compute_network.digital_asset_trading_vpc.name\n  allow {\n    protocol = \"tcp\"\n    ports    = [\"443\"]\n  }\n  source_ranges = [\"0.0.0.0/0\"]\n  target_tags   = [\"web-server\"]\n}\n",
  "fix_summary": "Restricted the firewall rule to only allow ingress traffic on port 443 from 0.0.0.0/0, as ports 80 and 8080 are not necessary for standard HTTPS traffic and may expose the server to unnecessary risk."
}
